import { BottomSheetView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import { RecoveryState } from "@unomed/react-native-matrix-sdk";
import { AuthService } from "modules/auth/service/AuthService";
import { EncryptionService } from "modules/encryption/service/EncryptionService";
import { NavigationContainerRef } from "modules/navigation/const";
import { useCallback, useEffect, useRef, useState } from "react";
import { Image } from "react-native";
import Toast from "react-native-toast-message";
import { Button, Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { usePreventSwipeBack } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  isBottomSheetOpen: boolean;
  setIsBottomSheetOpen: () => void;
}

export const SignOutBottomSheet: React.FC<Props> = ({
  isBottomSheetOpen,
  setIsBottomSheetOpen,
}) => {
  const sheetRef = useRef<AppBottomSheetRef>(null);
  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    RecoveryState.Unknown,
  );
  const isBackupEnabled =
    backupState === "enabled" ||
    (backupState === "unknown" &&
      (recoveryState === RecoveryState.Enabled ||
        recoveryState === RecoveryState.Incomplete));
  const [showBackupSetUpWarning, setShowBackupSetUpWarning] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);

  const signOut = async () => {
    try {
      setIsSigningOut(true);
      await AuthService.logout();
      handleCancel();
      NavigationContainerRef.reset({
        index: 0,
        routes: [{ name: "splash" }],
      });
      Toast.show({
        type: "success",
        text1: "Successfully signed out",
      });
    } catch (error) {
      console.error("Failed to logout: ", error);
      offlineToastHelper("Failed to sign out");
    } finally {
      setIsSigningOut(false);
    }
  };

  const handleClose = useCallback(() => {
    setIsBottomSheetOpen();
    setShowBackupSetUpWarning(false);
  }, [setIsBottomSheetOpen]);

  const handleCancel = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleSettings = useCallback(() => {
    handleCancel();
    NavigationContainerRef.navigate("encryption");
  }, [handleCancel]);

  const handleSignOut = useCallback(() => {
    if (!isBackupEnabled) {
      setShowBackupSetUpWarning(true);
      return;
    }

    signOut();
  }, [signOut]);

  usePreventSwipeBack(isBottomSheetOpen);

  useEffect(() => {
    const listener = EncryptionService.subscribeToBackupState((state) => {
      setBackupState(state);
    });

    return () => {
      listener.cancel();
    };
  }, []);

  useEffect(() => {
    const listener = EncryptionService.subscribeToRecoveryState((state) => {
      setRecoveryState(state);
    });

    return () => {
      listener.cancel();
    };
  }, []);

  return (
    <>
      {isSigningOut ? <Loading text="Signing out..." /> : null}
      <AppBottomSheet
        ref={sheetRef}
        isOpen={isBottomSheetOpen}
        onClose={handleClose}
      >
        <BottomSheetView>
          {showBackupSetUpWarning ? (
            <Block
              paddings={{
                paddingHorizontal: 20,
                paddingBottom: 20,
              }}
              flex={1}
              gap={40}
              align="center"
            >
              <Image source={require("assets/images/key.png")} />
              <Block gap={8} align="center">
                <Text size={TextSize.large} color={Colors.white}>
                  Recovery not set up
                </Text>
                <Text font="InstrumentSans-Regular" textAlign="center">
                  You are about to sign out of your last session. If you sign
                  out now, you will lose access to your encrypted messages.
                </Text>
              </Block>
              <Block gap={12} width="100%" paddings={[0, 52]}>
                <Button.Outline onPress={handleSettings}>
                  Settings
                </Button.Outline>
                <Button.Warning onPress={signOut}>
                  Sign out anyway
                </Button.Warning>
              </Block>
            </Block>
          ) : (
            <Block
              paddings={{
                paddingHorizontal: 20,
                paddingBottom: 20,
              }}
              gap={40}
            >
              <Block gap={8} align="center">
                <Text size={TextSize.large} color={Colors.white}>
                  Sign Out
                </Text>
                <Text font="InstrumentSans-Regular">
                  Are you sure you want to sign out?
                </Text>
              </Block>
              <Block gap={12} width="100%" paddings={[0, 52]}>
                <Button.Warning onPress={handleSignOut}>
                  Sign Out
                </Button.Warning>
                <Button.Ghost onPress={handleCancel}>Cancel</Button.Ghost>
              </Block>
            </Block>
          )}
        </BottomSheetView>
      </AppBottomSheet>
    </>
  );
};

import {
  BottomSheetScrollView,
  BottomSheetTextInput,
} from "@gorhom/bottom-sheet";
import { Block, Text, useAndroidBackHandler } from "@prototyp/skeletor";
import { resetToRoom } from "modules/navigation/utils";
import { RoomService } from "modules/room/service/RoomService";
import { type FC, useCallback, useRef, useState } from "react";
import { Button, Input, Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  isBottomSheetOpen: boolean;
  setIsBottomSheetOpen: (value: boolean) => void;
}

const ROOM_ADDRESS_REGEX = /^#.+:.+$/;

export const JoinRoom: FC<Props> = ({
  isBottomSheetOpen,
  setIsBottomSheetOpen,
}) => {
  const [roomAddress, setRoomAddress] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const sheetRef = useRef<AppBottomSheetRef>(null);

  const handleTextChange = (text: string) => {
    setRoomAddress(text);
    setError(null);
  };

  const handleClose = useCallback(() => {
    setIsBottomSheetOpen(false);
    setRoomAddress("");
    setError(null);
  }, [setIsBottomSheetOpen]);

  const handleCloseOnPress = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleJoinRoom = useCallback(async () => {
    const trimmedAddress = roomAddress.trim();

    if (!trimmedAddress) {
      setError("Please enter a room address.");
      return;
    }

    if (!ROOM_ADDRESS_REGEX.test(trimmedAddress)) {
      setError("Enter a valid room address.");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const roomId = await RoomService.joinRoomByAddress(trimmedAddress);

      resetToRoom(roomId);

      sheetRef.current?.close();
    } catch (err) {
      offlineToastHelper("Failed to join room");
      console.error("Failed to join room:", err);
    } finally {
      setLoading(false);
    }
  }, [roomAddress]);

  useAndroidBackHandler({
    handlePress: handleCloseOnPress,
    enabled: isBottomSheetOpen,
    disableDefault: isBottomSheetOpen,
  });

  return (
    <AppBottomSheet
      ref={sheetRef}
      isOpen={isBottomSheetOpen}
      enableContentPanningGesture={false}
      keyboardBehavior="interactive"
      keyboardBlurBehavior="restore"
      android_keyboardInputMode="adjustResize"
      onClose={handleClose}
    >
      <BottomSheetScrollView scrollEnabled={false}>
        <Block
          justify="space-between"
          flexDirection="column"
          flex={1}
          width="100%"
          gap={8}
          paddings={{
            paddingHorizontal: 12,
            paddingBottom: 36,
          }}
        >
          <Text
            size={TextSize.small}
            color={Colors.white}
            font="InstrumentSans-Bold"
            paddings={{ paddingHorizontal: 14 }}
          >
            Join room by address
          </Text>
          <Input
            placeholder="Enter room address"
            background={Colors.white5}
            value={roomAddress}
            onChangeText={handleTextChange}
            autoCapitalize="none"
            editable={!loading}
            InputComponent={BottomSheetTextInput}
          />

          {error ? (
            <Text
              size={TextSize.tiny}
              color="red"
              font="InstrumentSans-Regular"
              paddings={{ paddingHorizontal: 14 }}
              margins={{ marginBottom: 8 }}
            >
              {error}
            </Text>
          ) : (
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              font="InstrumentSans-Regular"
              paddings={{ paddingHorizontal: 14 }}
              margins={{ marginBottom: 8 }}
            >
              e.g. #room-name:matrix.org
            </Text>
          )}
          <Button.Primary onPress={handleJoinRoom} disabled={loading}>
            {loading ? "Joining..." : "Join room"}
          </Button.Primary>
          {loading && <Loading text="Joining room..." />}
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
import { Block, Text, useAndroidBackHandler } from "@prototyp/skeletor";
import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { NavigationContainerRef } from "modules/navigation/const";
import { RoomService } from "modules/room/service/RoomService";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Alert, Image, StyleSheet } from "react-native";
import Toast from "react-native-toast-message";
import { Button, Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { UserImage } from "shared/components/user-image/UserImage";
import { usePreventSwipeBack } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  isBottomSheetOpen: boolean;
  selectedMember: MemberDetailsPayload | null;
  roomId: string;
  onClose: () => void;
  onMemberAction?: (userId: string, action: "remove" | "ban" | "unban") => void;
}

export const MemberDetailsBottomSheet: React.FC<Props> = ({
  isBottomSheetOpen,
  selectedMember,
  roomId,
  onClose,
  onMemberAction,
}) => {
  const sheetRef = useRef<AppBottomSheetRef>(null);
  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
  const [memberPowerLevel, setMemberPowerLevel] = useState<number | null>(null);
  const [kickLevel, setKickLevel] = useState(50);
  const [banLevel, setBanLevel] = useState(50);

  const canRemove = useMemo(
    () =>
      userPowerLevel !== null &&
      memberPowerLevel !== null &&
      userPowerLevel >= kickLevel &&
      userPowerLevel > memberPowerLevel,
    [userPowerLevel, memberPowerLevel, kickLevel],
  );
  const canBan = useMemo(
    () =>
      userPowerLevel !== null &&
      memberPowerLevel !== null &&
      userPowerLevel >= banLevel &&
      userPowerLevel > memberPowerLevel,
    [userPowerLevel, memberPowerLevel, banLevel],
  );
  const isUser = useMemo(
    () => selectedMember?.userId === MatrixCore.instance?.userId(),
    [selectedMember],
  );
  const isBanned = useMemo(
    () => selectedMember?.membershipTag === MembershipState_Tags.Ban,
    [selectedMember],
  );
  const [activeAction, setActiveAction] = useState<
    "remove" | "ban" | "unban" | null
  >(null);

  const handleClose = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleViewProfile = useCallback(() => {
    sheetRef.current?.close();

    if (isUser) {
      NavigationContainerRef.navigate("userProfile");
      return;
    }
    if (!selectedMember) return;

    NavigationContainerRef.navigate("profile", {
      userId: selectedMember.userId,
      initialProfile: {
        userId: selectedMember.userId,
        displayName: selectedMember.displayName,
        avatarUrl: selectedMember.avatarUrl ?? undefined,
      },
    });
  }, [isUser, selectedMember]);

  const handleConfirmAction = useCallback(
    async (action: "remove" | "ban" | "unban", reason: string) => {
      if (!selectedMember) return;
      try {
        setActiveAction(action);

        onMemberAction?.(selectedMember.userId, action);

        sheetRef.current?.close();

        if (action === "ban") {
          await RoomService.banUserFromRoom(
            roomId,
            selectedMember.userId,
            reason || undefined,
          );
        } else if (action === "unban") {
          await RoomService.unbanUserFromRoom(
            roomId,
            selectedMember.userId,
            reason || undefined,
          );
        } else {
          await RoomService.removeUserFromRoom(
            roomId,
            selectedMember.userId,
            reason || undefined,
          );
        }

        Toast.show({
          type: "success",
          text1: `User ${action === "ban" ? "banned" : action === "unban" ? "unbanned" : "removed"} successfully`,
        });
        NavigationContainerRef.goBack();
      } catch (error) {
        console.error(`Failed to ${action} user:`, error);
        offlineToastHelper(`Failed to ${action} user`);
      } finally {
        setActiveAction(null);
      }
    },
    [selectedMember, roomId, onMemberAction],
  );

  const handleUserAction = useCallback(
    (action: "remove" | "ban" | "unban") => {
      if (!selectedMember) return;

      const actionText = action === "ban" ? "banning" : "removing";
      const actionTitle = action === "ban" ? "Ban User" : "Remove User";
      const confirmButtonText =
        action === "ban" ? "Ban" : action === "unban" ? "Unban" : "Remove";

      if (action === "unban") {
        Alert.alert(
          "Unban User",
          `Are you sure you want to unban ${selectedMember.displayName}?`,
          [
            {
              text: "Cancel",
              style: "cancel",
            },
            {
              text: "Unban",
              onPress: () => handleConfirmAction("unban", ""),
            },
          ],
        );
        return;
      }

      Alert.prompt(
        actionTitle,
        `Enter a reason for ${actionText} ${selectedMember.displayName} (optional):`,
        [
          {
            text: "Cancel",
            style: "cancel",
          },
          {
            text: "Continue",
            onPress: (reason?: string) => {
              Alert.alert(
                "Are you sure?",
                `Are you sure you want to ${action} ${selectedMember.displayName} from this room?`,
                [
                  {
                    text: "Cancel",
                    style: "cancel",
                  },
                  {
                    text: confirmButtonText,
                    style: "destructive",
                    onPress: () => handleConfirmAction(action, reason || ""),
                  },
                ],
              );
            },
          },
        ],
        "plain-text",
      );
    },
    [selectedMember, handleConfirmAction],
  );

  const handleRemoveUser = useCallback(
    () => handleUserAction("remove"),
    [handleUserAction],
  );

  const handleBanUser = useCallback(
    () => handleUserAction("ban"),
    [handleUserAction],
  );

  const handleUnbanUser = useCallback(
    () => handleUserAction("unban"),
    [handleUserAction],
  );

  useAndroidBackHandler({
    handlePress: handleClose,
    enabled: isBottomSheetOpen,
    disableDefault: isBottomSheetOpen,
  });

  usePreventSwipeBack(isBottomSheetOpen);

  useEffect(() => {
    if (!isBottomSheetOpen || !selectedMember) return;
    RoomService.getUserPowerLevel(roomId)
      .then(setUserPowerLevel)
      .catch(console.error);
    RoomService.getUserPowerLevel(roomId, selectedMember.userId)
      .then(setMemberPowerLevel)
      .catch(console.error);
    RoomService.getRoomPowerLevels(roomId)
      .then((pl) => {
        if (!pl) return;
        const vals = pl.values();
        setKickLevel(Number(vals.kick));
        setBanLevel(Number(vals.ban));
      })
      .catch(console.error);
  }, [isBottomSheetOpen, selectedMember]);

  if (!selectedMember) return null;

  return (
    <>
      {activeAction && (
        <Loading
          text={
            activeAction === "ban"
              ? "Banning user..."
              : activeAction === "unban"
                ? "Unbanning user..."
                : "Removing user..."
          }
        />
      )}
      <AppBottomSheet
        ref={sheetRef}
        isOpen={isBottomSheetOpen}
        enableContentPanningGesture={false}
        onClose={onClose}
      >
        <BottomSheetScrollView scrollEnabled={false}>
          <Block
            justify="space-between"
            flexDirection="column"
            flex={1}
            width="100%"
            gap={16}
            paddings={{
              paddingHorizontal: 20,
              paddingBottom: 56,
            }}
          >
            <Block align="center" gap={16} margins={{ marginBottom: 60 }}>
              <UserImage
                avatarUrl={selectedMember.avatarUrl}
                displayName={selectedMember.displayName}
                width={120}
                height={120}
                borderRadius={999}
              />
              <Block align="center" gap={4}>
                <Text
                  size={TextSize.large}
                  color={Colors.white}
                  font="InstrumentSans-Bold"
                >
                  {selectedMember.displayName}
                </Text>
                <Text color={Colors.white50} font="InstrumentSans-Regular">
                  {selectedMember.userId}
                </Text>
              </Block>
            </Block>
            <Block gap={20}>
              <Button.Wrapper onPress={handleViewProfile}>
                <Block
                  width="100%"
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={{ paddingBottom: 20 }}
                  border={{
                    borderBottomWidth: 1,
                    borderColor: Colors.white5,
                  }}
                >
                  <Image
                    source={require("assets/icons/user.png")}
                    style={styles.icon}
                    tintColor={Colors.white50}
                  />
                  <Text color={Colors.white}>View Profile</Text>
                </Block>
              </Button.Wrapper>
              {canRemove && !isUser && !isBanned && (
                <Button.Wrapper onPress={handleRemoveUser}>
                  <Block
                    width="100%"
                    flexDirection="row"
                    align="center"
                    gap={12}
                    paddings={{ paddingBottom: 20 }}
                    border={{
                      borderBottomWidth: 1,
                      borderColor: Colors.white5,
                    }}
                  >
                    <Image
                      source={require("assets/icons/close.png")}
                      style={styles.icon}
                      tintColor={Colors.white50}
                    />
                    <Text color={Colors.white}>Remove user</Text>
                  </Block>
                </Button.Wrapper>
              )}
              {canBan && !isUser && !isBanned && (
                <Button.Wrapper onPress={handleBanUser}>
                  <Block
                    width="100%"
                    flexDirection="row"
                    align="center"
                    gap={12}
                    paddings={{ paddingBottom: 20 }}
                    border={{
                      borderBottomWidth: 1,
                      borderColor: Colors.white5,
                    }}
                  >
                    <Image
                      source={require("assets/icons/ban.png")}
                      style={styles.icon}
                      tintColor={Colors.white50}
                    />
                    <Text color={Colors.white}>Ban user</Text>
                  </Block>
                </Button.Wrapper>
              )}
              {canBan && !isUser && isBanned && (
                <Button.Wrapper onPress={handleUnbanUser}>
                  <Block
                    width="100%"
                    flexDirection="row"
                    align="center"
                    gap={12}
                    paddings={{ paddingBottom: 20 }}
                    border={{
                      borderBottomWidth: 1,
                      borderColor: Colors.white5,
                    }}
                  >
                    <Image
                      source={require("assets/icons/ban.png")}
                      style={styles.icon}
                      tintColor={Colors.white50}
                    />
                    <Text color={Colors.white}>Unban user</Text>
                  </Block>
                </Button.Wrapper>
              )}
            </Block>
          </Block>
        </BottomSheetScrollView>
      </AppBottomSheet>
    </>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 24,
    height: 24,
  },
});

import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import type { UserProfile } from "@unomed/react-native-matrix-sdk";
import { format, isToday } from "date-fns";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { useEffect, useState } from "react";
import { AppBottomSheet } from "shared/components/bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { UserProfileImage } from "../user-profile-image";

interface RowProps {
  userId: string;
  timestamp: number | null;
}

const SeenByRow: React.FC<RowProps> = ({ userId, timestamp }) => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const displayName =
    profile?.displayName ?? userId.replace("@", "").split(":")[0];

  useEffect(() => {
    MatrixCore.getClient().getProfile(userId).then(setProfile).catch();
  }, [userId]);

  return (
    <Block
      flexDirection="row"
      align="center"
      gap={12}
      paddings={{ paddingVertical: 12 }}
      border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
    >
      <UserProfileImage user={profile} width={36} height={36} />
      <Block flex={1} gap={2}>
        <Text color={Colors.white} font="InstrumentSans-Bold">
          {displayName}
        </Text>
        <Text
          size={TextSize.small}
          color={Colors.white50}
          font="InstrumentSans-Regular"
        >
          {userId}
        </Text>
      </Block>
      {!!timestamp && (
        <Text
          size={TextSize.small}
          color={Colors.white50}
          font="InstrumentSans-Regular"
        >
          {isToday(timestamp)
            ? format(timestamp, "HH:mm")
            : format(timestamp, "MMM d, HH:mm")}
        </Text>
      )}
    </Block>
  );
};

interface Props {
  isOpen: boolean;
  users: TimelineSeenByUser[];
  onClose: () => void;
}

export const SeenByBottomSheet: React.FC<Props> = ({
  isOpen,
  users,
  onClose,
}) => {
  return (
    <AppBottomSheet
      isOpen={isOpen}
      onClose={onClose}
      enableContentPanningGesture={false}
    >
      <BottomSheetScrollView stickyHeaderIndices={[0]}>
        <Block
          paddings={{ paddingHorizontal: 20, paddingTop: 4, paddingBottom: 8 }}
          background={Colors.blackMinus1}
        >
          <Text
            font="InstrumentSans-Bold"
            color={Colors.white}
            size={TextSize.medium}
            margins={{ marginBottom: 16 }}
          >
            Seen by
          </Text>
        </Block>
        <Block paddings={{ paddingHorizontal: 20, paddingBottom: 56 }}>
          {users.map(({ userId, timestamp }) => (
            <SeenByRow key={userId} userId={userId} timestamp={timestamp} />
          ))}
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

