import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { SkeletorProvider } from "@prototyp/skeletor";
import { NavigationContainer } from "@react-navigation/native";
import { CallKitProvider } from "modules/call/provider";
import {
  IgnoredUsersProvider,
  RoomListProvider,
  SyncLifecycleProvider,
  VerificationProvider,
} from "modules/matrix-client/providers";
import { RootNavigator } from "modules/navigation/components";
import { NavigationContainerRef } from "modules/navigation/const";
import { NetworkStatusBanner } from "modules/network/provider";
import { PushNotificationsProvider } from "modules/push-notifications/provider";
import { AudioPlaybackProvider } from "modules/recorder-player/providers";
import { ScreenLockOverlay } from "modules/screen-lock/components";
import { ScreenLockProvider } from "modules/screen-lock/provider";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import "react-native-reanimated";
import { SafeAreaProvider } from "react-native-safe-area-context";
import Toast from "react-native-toast-message";
import { IpadLayoutWrapper } from "screens/home/fragments";
import { ImageViewerModal, MediaViewerModal } from "shared/components";
import { SkeletonDefault, ThemeDefault, ToastConfig } from "shared/const";

export const App: React.FC = () => {
  return (
    <SafeAreaProvider>
      <SkeletorProvider {...SkeletonDefault}>
        <GestureHandlerRootView>
          <BottomSheetModalProvider>
            <AudioPlaybackProvider>
              <NavigationContainer
                ref={NavigationContainerRef}
                theme={ThemeDefault}
              >
                <CallKitProvider />
                <VerificationProvider />
                <RoomListProvider />
                <IgnoredUsersProvider />
                <SyncLifecycleProvider />
                <PushNotificationsProvider />
                <ScreenLockProvider />
                <IpadLayoutWrapper>
                  <NetworkStatusBanner />
                  <RootNavigator />
                  <ImageViewerModal />
                  <MediaViewerModal />
                  <Toast
                    config={ToastConfig}
                    position="top"
                    topOffset={140}
                    visibilityTime={2000}
                  />
                  <ScreenLockOverlay />
                </IpadLayoutWrapper>
              </NavigationContainer>
            </AudioPlaybackProvider>
          </BottomSheetModalProvider>
        </GestureHandlerRootView>
      </SkeletorProvider>
    </SafeAreaProvider>
  );
};

