    44	export const StartChat: React.FC<
    45	  NativeStackScreenProps<Routes, "startChat">
    46	> = ({ navigation }) => {
    47	  const [isJoinRoomBottomSheetOpen, setIsJoinRoomBottomSheetOpen] =
    48	    useState(false);
