   155	                <Image source={item.image} style={styles.image} />
   156	                <Text font="InstrumentSans-Bold">{item.label}</Text>
   157	              </Block>
   158	              <Image
   159	                source={require("assets/icons/caret-left.png")}
   160	                width={24}
   161	                height={24}
   162	                style={styles.caret}
   163	                tintColor={Colors.white50}
   164	              />
   165	            </Block>
   166	          </Button.Wrapper>
   167	        )}
   168	      />
   169	      <JoinRoom
   170	        isBottomSheetOpen={isJoinRoomBottomSheetOpen}
   171	        setIsBottomSheetOpen={setIsJoinRoomBottomSheetOpen}
   172	      />
   173	      <SendInviteBottomSheet
   174	        isBottomSheetOpen={isInviteBottomSheetOpen}
   175	        selectedUser={selectedUser}
   176	        isLoading={isCreatingChat}
   177	        setIsBottomSheetOpen={() => setIsInviteBottomSheetOpen(false)}
   178	        onSendInvite={handleSendInvite}
   179	      />
   180	    </ScreenLayout>
   181	  );
   182	};
