  {
    title: "About",
    icon: require("assets/icons/info.png"),
    routeName: "about",
  },
];

export const Settings: React.FC<NativeStackScreenProps<Routes, "settings">> = ({
  navigation,
}) => {
  const [isSignOutBottomSheetOpen, setIsSignOutBottomSheetOpen] =
    useState(false);
  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
  const [blockedUserIds, setBlockedUserIds] = useState<string[]>([]);
  const canDeactivateAccount = AuthService.canDeactivateAccount();
  const isFocused = useIsFocused();

  useEffect(() => {
    UserService.getBlockedUsers().then(setBlockedUserIds).catch(console.error);
  }, [isFocused]);

  const handleOnPress = (routeName: SettingsRouteName) => {
    if (routeName === "screenLock") {
      if (screenLockPin) {
        navigation.navigate("verifyPin");
      } else navigation.navigate("setupScreenLock");

      return;
    }
    navigation.navigate(routeName);
  };

  return (
    <ScreenLayout>
      <Block align="center" gap={40}>
        <GoBackHeader title="Settings" margins={0} />
        <UserInfoItem />
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
        >
          {ITEMS.slice(0, 3).map((item, index, array) => (
            <SettingsListItem
              key={item.title}
              title={item.title}
              icon={item.icon}
              onPress={() => handleOnPress(item.routeName)}
              showSeparator={
                index !== array.length - 1 || !!blockedUserIds.length
              }
            />
          ))}
          {!!blockedUserIds.length && (
            <SettingsListItem
              title="Blocked Users"
              icon={require("assets/icons/ban.png")}
              onPress={() =>
                navigation.navigate("blockedUsers", { blockedUserIds })
              }
              showSeparator={false}
            />
          )}
        </Block>
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
        >
          {ITEMS.slice(3).map((item, index, array) => (
            <SettingsListItem
              key={item.title}
              title={item.title}
              icon={item.icon}
              onPress={() => handleOnPress(item.routeName)}
              showSeparator={index !== array.length - 1}
            />
          ))}
        </Block>
        <Block
          border={{ borderRadius: 16 }}
          width="100%"
          background={Colors.white5}
        >
          <Button.Wrapper
            onPress={() => setIsSignOutBottomSheetOpen(true)}
            style={styles.button}
          >
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              paddings={[20, 12]}
              width="100%"
              border={{ borderRadius: 16 }}
            >
              <Image
                source={require("assets/icons/sign-out.png")}
                width={24}
                height={24}
                tintColor={Colors.warning}
              />
              <Text size={TextSize.base} color={Colors.warning}>
                Sign Out
              </Text>
            </Block>
          </Button.Wrapper>
          {canDeactivateAccount && (
            <Button.Wrapper
              onPress={() => navigation.navigate("deactivateAccount")}
              style={styles.button}
            >
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[20, 12]}
                width="100%"
                border={{
                  borderRadius: 16,
                  borderTopWidth: 1,
                  borderColor: Colors.white5,
                }}
              >
                <Image
                  source={require("assets/icons/warning-triangle.png")}
                  width={24}
                  height={24}
                  tintColor={Colors.warning}
                />
                <Text size={TextSize.base} color={Colors.warning}>
                  Deactivate Account
                </Text>
              </Block>
            </Button.Wrapper>
          )}
        </Block>
      </Block>
      <SignOutBottomSheet
        isBottomSheetOpen={isSignOutBottomSheetOpen}
        setIsBottomSheetOpen={() => setIsSignOutBottomSheetOpen(false)}
      />
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  button: {
    width: "100%",
  },
});

import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { FlashList } from "@shopify/flash-list";
import type { UserProfile } from "@unomed/react-native-matrix-sdk";
import { resetToRoom } from "modules/navigation/utils";
import { RoomService } from "modules/room/service/RoomService";
import { UserService } from "modules/user/service/UserService";
import { useEffect, useState } from "react";
import { Image, type ImageSourcePropType, StyleSheet } from "react-native";
import Share from "react-native-share";
import { JoinRoom } from "screens/join-room/JoinRoom";
import { Button, Loading, ScreenLayout } from "shared/components";
import { Colors } from "shared/styles";
import { Header, SearchHeader, SendInviteBottomSheet } from "./fragments";

type Option = {
  id: string;
  label: string;
  image: ImageSourcePropType;
  type: keyof Routes;
};

const OPTIONS: Option[] = [
  {
    id: "1",
    label: "Create room",
    image: require("assets/icons/create-room.png"),
    type: "createRoom",
  },
  {
    id: "2",
    label: "Invite people",
    image: require("assets/icons/invite-people.png"),
    type: "invitePeople",
  },
  {
    id: "3",
    label: "Join room by address",
    image: require("assets/icons/create-room.png"),
    type: "joinRoom",
  },
];

export const StartChat: React.FC<
  NativeStackScreenProps<Routes, "startChat">
> = ({ navigation }) => {
  const [isJoinRoomBottomSheetOpen, setIsJoinRoomBottomSheetOpen] =
    useState(false);
  const [isInviteBottomSheetOpen, setIsInviteBottomSheetOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [searchResults, setSearchResults] = useState<UserProfile[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isCreatingChat, setIsCreatingChat] = useState(false);

  useEffect(() => {
    if (!search) {
      setSearchResults([]);
      return;
    }

    const timeoutId = setTimeout(async () => {
      try {
        setIsSearching(true);
        const people = await UserService.searchUsers(search);
        setSearchResults(people.results);
      } catch (error) {
        console.error(error);
      } finally {
        setIsSearching(false);
      }
    }, 350);

    return () => clearTimeout(timeoutId);
  }, [search]);

  const onPress = async (item: Option) => {
    if (item.type === "invitePeople") {
      Share.open({
        message:
          "Hey, I'm using Cloak and Dagger! Download it now: https://cloak.app",
      });
      return;
    }

    if (item.type === "createRoom") navigation.navigate("createRoom");

    if (item.type === "joinRoom") setIsJoinRoomBottomSheetOpen(true);
  };

  const handleUserPress = async (user: UserProfile) => {
    try {
      setIsSearching(true);
      const existingRoomId = await RoomService.getExistingDirectRoom(
        user.userId,
      );

      if (existingRoomId) {
        resetToRoom(existingRoomId);
        return;
      }

      setSelectedUser(user);
      setIsInviteBottomSheetOpen(true);
    } catch (error) {
      console.error(error);
    } finally {
      setIsSearching(false);
    }
  };

  const handleSendInvite = async () => {
    if (!selectedUser) return;

    try {
      setIsCreatingChat(true);
      const roomId = await RoomService.getOrCreateDirectRoom(
        selectedUser.userId,
      );
      setIsInviteBottomSheetOpen(false);
      resetToRoom(roomId);
    } catch (error) {
      console.error(error);
    } finally {
      setIsCreatingChat(false);
    }
  };

  return (
    <ScreenLayout background={Colors.blackMinus1} type="modal">
      {(isSearching || isCreatingChat) && <Loading />}
      <Header />
      <FlashList
        contentContainerStyle={styles.wrapper}
        data={search ? [] : OPTIONS}
        ListHeaderComponent={
          <SearchHeader
            search={search}
            searchResults={searchResults}
            setSearch={setSearch}
            onUserPress={handleUserPress}
          />
        }
        renderItem={({ item }) => (
          <Button.Wrapper onPress={() => onPress(item)}>
            <Block
              paddings={[20, 16]}
              background={Colors.white5}
              border={{ borderRadius: 12 }}
              flexDirection="row"
              align="center"
              justify="space-between"
            >
              <Block flexDirection="row" align="center" gap={8}>
                <Image source={item.image} style={styles.image} />
                <Text font="InstrumentSans-Bold">{item.label}</Text>
              </Block>
              <Image
                source={require("assets/icons/caret-left.png")}
                width={24}
                height={24}
                style={styles.caret}
                tintColor={Colors.white50}
              />
            </Block>
          </Button.Wrapper>
        )}
      />
      <JoinRoom
        isBottomSheetOpen={isJoinRoomBottomSheetOpen}
        setIsBottomSheetOpen={setIsJoinRoomBottomSheetOpen}
      />
      <SendInviteBottomSheet
        isBottomSheetOpen={isInviteBottomSheetOpen}
        selectedUser={selectedUser}
        isLoading={isCreatingChat}
        setIsBottomSheetOpen={() => setIsInviteBottomSheetOpen(false)}
        onSendInvite={handleSendInvite}
      />
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  wrapper: {
    gap: 12,
  },
  image: {
    width: 24,
    height: 24,
  },
  caret: {
    width: 24,
    height: 24,
    transform: [{ rotate: "180deg" }],
  },
});

